    def lookup_tier(self, pokedex_id):
        if pokedex_id in self.tier_1_ids:
            return 1
        elif pokedex_id in self.tier_2_ids:
            return 2
        elif pokedex_id in self.tier_3_ids:
            return 3
        elif pokedex_id in self.tier_4_ids:
            return 4
        return 0 
    
    def get_tier_region_pool(self, tier: int, region: str) -> list:
        """
        Returns a list of Pokedex IDs that belong to the specified tier and region.

        Args:
            tier (int): The desired tier (1, 2, 3, or 4).
            region (str): The desired region (e.g., "kanto", "johto", etc., lowercase).

        Returns:
            list: A list of Pokedex IDs that are in both the specified tier and region.
                  Returns an empty list if the tier or region is invalid, or if there
                  are no Pokémon matching the criteria.
        """
        tier_ids = []
        if tier == 1:
            tier_ids = self.tier_1_ids
        elif tier == 2:
            tier_ids = self.tier_2_ids
        elif tier == 3:
            tier_ids = self.tier_3_ids
        elif tier == 4:
            tier_ids = self.tier_4_ids
        else:
            return []  # Invalid tier

        region_ids = self.region_map.get(region.lower())

        if not region_ids:
            return []  # Invalid region or region not found

        # Find the intersection of the tier_ids and region_ids
        # Convert to sets for efficient intersection finding
        return list(set(tier_ids) & set(region_ids))